4	/**
5	 * 整個專案的 entry point，根據 command line arguments 執行不同的功能。
6	 * - server: 開始執行 api server
7	 * - gen: 產生 openapi 規格檔案
8	 */
9	function main() {
10	  const command = process.argv[2];
11	
12	  switch (command) {
13	    case "server":
14	      server.exec();
15	      break;
16	    case "gen":
17	      gen.exec();
18	      break;
19	    default:
20	      server.exec();
21	      break;
22	  }
23	}
24	
25	main();
