112	function createSwagger(server: FastifyInstance) {
113	  // Display swagger api docs in dev or local environment (only when file exists)
114	  if (env.env !== "prod" && fs.existsSync(OPENAPI_FILE)) {
115	    try {
116	      const swaggerDocument = YAML.load(OPENAPI_FILE);
117	      server.register(fastifySwagger, { openapi: swaggerDocument });
118	      server.register(fastifySwaggerUi, {
119	        routePrefix: "/api/v3/api-docs",
120	      });
121	    } catch (err) {
122	      logger.error(`Can't open ${OPENAPI_FILE}`);
123	    }
124	  }
125	}
