398	/**
399	 * 建立 server 並註冊所有的 api routes
400	 */
401	export async function setupServer({
402	  addDropService,
403	  adminAuthService,
404	  allocationService,
405	  vacationCourseService,
406	  vacationCourseExtStuService,
407	  vacationCourseNtuStuService,
408	  configService,
409	  courseService,
410	  courseCollectionService,
411	  courseSelectionService,
412	  courseTableService,
413	  devCourseTableService,
414	  devUserService,
415	  operationRecordService,
416	  rbacRepo,
417	  rbacService,
418	}: Services) {
419	  const server = createServer({
420	    healthCheckPath: "/api/v3/healthz",
421	    apiDocs: {
422	      path: "/api/v3/docs",
423	      filePath: "openapi.yaml",
424	    },
425	  });
426	  server.register(createAddDropRoutes({ addDropService }));
427	  server.register(createAdminAuthRoutes({ adminAuthService }));
428	  server.register(createRbacRoutes({ rbacService, rbacRepo }));
429	  server.register(createAllocationAdminRoutes({ allocationService, rbacRepo }));
430	  server.register(createVacationCourseRoutes({ vacationCourseService }));
431	  server.register(
432	    createVacationCourseAdminRoutes({ vacationCourseService, rbacRepo }),
433	  );
434	  server.register(
435	    createVacationCourseExtStuRoutes({ vacationCourseExtStuService }),
436	  );
437	  server.register(
438	    createVacationCourseExtStuAdminRoutes({
439	      vacationCourseExtStuService,
440	      rbacRepo,
441	    }),
442	  );
443	  server.register(
444	    createVacationCourseNtuStuAdminRoutes({
445	      vacationCourseNtuStuService,
446	      rbacRepo,
447	    }),
448	  );
449	  server.register(
450	    createVacationCourseNtuStuRoutes({ vacationCourseNtuStuService }),
451	  );
452	  server.register(createConfigRoutes({ configService }));
453	  server.register(createConfigAdminRoutes({ configService, rbacRepo }));
454	  server.register(createCourseRoutes({ courseService }));
455	  server.register(createCourseCollectionRoutes({ courseCollectionService }));
456	  server.register(createCourseSelectionRoutes({ courseSelectionService }));
457	  server.register(createCourseTableRoutes({ courseTableService }));
458	  server.register(createOperationRecordRoutes({ operationRecordService }));
459	
460	  // 只有在非 production 環境才會啟用 dev routes
461	  if (env.env !== "prod") {
462	    server.register(createDevAddDropRoutes({ addDropService }));
463	    server.register(createDevCourseTableRoutes({ devCourseTableService }));
464	    server.register(createDevUserRoutes({ devUserService }));
465	    server.register(createDevCourseSelectionRoutes({ courseSelectionService }));
466	    createSwagger(server);
467	  }
468	
469	  await server.ready();
470	  return server;
471	}
472	
473	export async function startServer(server: ServerInstance) {
474	  try {
475	    const port = 8080;
476	    const host = "0.0.0.0";
477	    await server.listen({ port, host });
478	    logger.info(`Server started on port ${port}`);
479	
480	    process.on("SIGINT", async () => {
481	      logger.info("Received SIGINT. Closing server gracefully...");
482	      try {
483	        await server.close();
484	        logger.info("Server closed");
485	        process.exit(0);
486	      } catch (err) {
487	        logger.error("Error closing server:", err);
488	        process.exit(1);
489	      }
490	    });
491	
492	    process.on("SIGTERM", async () => {
493	      logger.info("Received SIGTERM. Closing server gracefully...");
494	      try {
495	        await server.close();
496	        logger.info("Server closed");
497	        process.exit(0);
498	      } catch (err) {
499	        logger.error("Error closing server:", err);
500	        process.exit(1);
501	      }
502	    });
503	  } catch (err) {
504	    logger.error("Server started failed");
505	    logger.error(err instanceof Error ? err.stack : String(err));
506	    logger.error({
507	      errType: typeof err,
508	      errJson: JSON.stringify(err),
509	      errStr: String(err),
510	    });
511	    process.exit(1);
512	  }
513	}
514	
515	/**
516	 * 開始執行 api server
517	 */
518	export async function exec() {
519	  try {
520	    const services = setupRealServices();
521	    const server = await setupServer(services);
522	    await startServer(server);
523	  } catch (err) {
524	    logger.error("exec() failed:");
525	    logger.error(err instanceof Error ? err.stack : err);
526	    process.exit(1);
527	  }
528	}
