14	export type CreateRoutes<T> = (
15	  services: T,
16	) => (server: FastifyInstance) => Promise<void>;
17	
18	/**
19	 * HTTP methods.
20	 */
21	type Method = "get" | "post" | "patch" | "delete" | "put";
22	
23	interface CreateRouteProps<TParams, TQuery, TBody, TResponse> {
24	  /**
25	   * The express router to handle the route.
26	   */
27	  server: FastifyInstance;
28	
29	  /**
30	   * The base path, for registering api docs only by concatenating with path, defaults to "".
31	   * @example /auth
32	   */
33	  basePath?: string;
34	
35	  /**
36	   * The path after base path, for registering express router and api docs, e.g. /login/email.
37	   * @example /login/email
38	   */
39	  path: string;
40	
41	  /**
42	   * The HTTP method.
43	   */
44	  method: Method;
45	
46	  /**
47	   * A brief description of the route to display on api docs.
48	   */
49	  summary?: string;
50	
51	  /**
52	   * A full description of the route to display on api docs.
53	   */
54	  description?: string;
55	
56	  /**
57	   * A list of tags to display on api docs.
58	   */
59	  tags?: string[];
60	
61	  /**
62	   * If the request needs to be authenticated to access by checking the auth token on the header, defaults to true.
63	   * Notes: if true, it will be handled by isAuthenticated middleware.
64	   */
65	  needAuthenticated: boolean;
66	
67	  /**
68	   * Schemas to validate payload of request and response.
69	   * Notes: if not undefined, it will be handled by validateRequestMiddleware and validateResponseMiddleware.
70	   */
71	  schemas: {
72	    request: RequestSchema<TParams, TQuery, TBody>;
73	    response: ResponseSchema<TResponse> | ResponseSchema<TResponse>["schema"];
74	  };
75	
76	  errors?: CustomError[];
77	
78	  /**
79	   * 後台權限檢查（RBAC）。設定後會在驗證登入之後、呼叫 handler 之前自動執行，
80	   * 不需在 handler 內手動呼叫 assertPermission。
81	   * @example { assert: assertPermission, code: "vacation-course:manage" }
82	   */
83	  permission?: {
84	    assert: AssertPermission;
85	    code: string;
86	  };
87	
88	  /**
89	   * The request handler.
90	   */
91	  handler: (
92	    params: TParams & TQuery & TBody & { userId: string; lang: Language },
93	  ) => Promise<TResponse> | TResponse;
94	}
