96	/**
97	 * Create a route with handler, and register it to api docs by request and response schemas automatically.
98	 */
99	export function createRoute<TParams, TQuery, TBody, TResponse>({
100	  server,
101	  basePath = "",
102	  path,
103	  method,
104	  summary,
105	  description,
106	  tags,
107	  needAuthenticated,
108	  schemas: { request: requestSchema, response },
109	  errors = [],
110	  permission,
111	  handler,
112	}: CreateRouteProps<TParams, TQuery, TBody, TResponse>) {
113	  const responseSchema =
114	    response instanceof ZodSchema ? response : response?.schema;
115	  const responseStatusCode =
116	    response instanceof ZodSchema || response === undefined
117	      ? 200
118	      : response.statusCode;
119	
120	  registerRouteToApiDocs({
121	    method,
122	    path: basePath + path,
123	    description,
124	    summary,
125	    tags,
126	    request: requestSchema,
127	    response: { schema: responseSchema, statusCode: responseStatusCode },
128	    errors,
129	    needAuthenticated,
130	  });
131	
132	  server.route({
133	    method,
134	    url: path,
135	    handler: async (request, reply) => {
136	      let userId: string | undefined;
137	      if (needAuthenticated !== false) {
138	        try {
139	          const [, token] = request.headers.authorization?.split(" ") || [];
140	          const authPayload = verifyAuthToken(token, env.accessJwtSecret);
141	          userId = authPayload.id;
142	        } catch (e) {
143	          throw new UnauthorizedError();
144	        }
145	      }
146	
147	      if (permission && userId) {
148	        await permission.assert(userId, permission.code);
149	      }
