3	/**
4	 * The type of the payload encapsulated in the auth token.
5	 */
6	interface AuthTokenPayload {
7	  id: string;
8	  nameID?: string;
9	  nameIDFormat?: string;
10	  sessionIndex?: string;
11	}
12	
13	const authTokenExpiresIn = 60 * 60; // 1 hour
14	
15	/**
16	 * Generate a jwt token as auth token for authenticating a user.
17	 * @param userId - The id of the user of the auth token.
18	 * @see https://www.npmjs.com/package/jsonwebtoken
19	 */
20	export function generateAuthToken(
21	  {
22	    userId,
23	    ...optionalPayload
24	  }: {
25	    userId: string;
26	    nameID?: string;
27	    nameIDFormat?: string;
28	    sessionIndex?: string;
29	  },
30	  secret: string,
31	): string {
32	  const payload: AuthTokenPayload = {
33	    ...optionalPayload,
34	    id: userId,
35	  };
36	  const token = jwt.sign(payload, secret, {
37	    expiresIn: authTokenExpiresIn,
38	  });
39	  return token;
40	}
41	
42	/**
43	 * Verify and decode the auth token to its payload.
44	 * @param token - The token to verify and decode;
45	 * @see https://www.npmjs.com/package/jsonwebtoken
46	 */
47	export function verifyAuthToken(
48	  token: string,
49	  secret: string,
50	): AuthTokenPayload {
51	  const payload = jwt.verify(token, secret);
52	  if (typeof payload === "string") {
53	    throw new Error("Bad auth token format");
54	  }
55	  return payload as AuthTokenPayload;
56	}
