68	/**
69	 * 一門課在某個選課階段的狀態
70	 */
71	export type ResolvedCourseState = {
72	  courseId: string;
73	  /** 造成此狀態的選課階段 */
74	  phase: ProgressPhase;
75	  /** 未選上的原因（落選原因或「學生自行退選」）；已選上時為 undefined */
76	  reason?: string | null;
