79	/**
80	 * 課程在整個學期的最終狀態（已跨階段 reduce，同一門課只會出現在其中一邊）
81	 */
82	export type ResolvedCourseStates = {
83	  assignedCourses: ResolvedCourseState[];
84	  unassignedCourses: ResolvedCourseState[];
85	};
86	
87	/**
88	 * 跨階段 reduce 出每門課的最終狀態。
89	 *
90	 * 已選上／未選上的記錄跨階段是 append-only 的（在加退選退掉一門初選選上的課，
91	 * 不會刪除初選那筆已選上記錄，只會在加退選的課表新增一筆未選上記錄），因此
92	 * 一門課可能同時存在於多個階段的課表。此處取「階段最晚」的那筆記錄為準：
93	 *
94	 *   初選二階 assigned + 加退選一 unassigned → 退掉了
95	 *   初選二階 unassigned + 加退選一 assigned → 選上了
96	 *
97	 * 同一階段內 assigned / unassigned 互斥（寫入時保證），故不需處理同階段的平手；
98	 * 但為了容錯舊資料，同階段兩者並存時以 unassigned 為準（不誤報學生選上）。
99	 */
100	export function reduceSemesterCourseTables(
101	  courseTables: RawSemesterCourseTable[],
102	): ResolvedCourseStates {
103	  type Latest = {
104	    order: number;
105	    assigned: boolean;
106	    state: ResolvedCourseState;
107	  };
108	  const latestByCourseId = new Map<string, Latest>();
109	
110	  const consider = (candidate: Latest) => {
111	    const current = latestByCourseId.get(candidate.state.courseId);
112	    if (
113	      !current ||
114	      candidate.order > current.order ||
115	      // 同階段平手時，unassigned 勝出
116	      (candidate.order === current.order && !candidate.assigned)
117	    ) {
118	      latestByCourseId.set(candidate.state.courseId, candidate);
119	    }
120	  };
121	
122	  for (const { phase, assignedCourses, unassignedCourses } of courseTables) {
123	    const order = getProgressPhaseOrder(phase);
124	
125	    for (const { courseId } of assignedCourses) {
126	      consider({ order, assigned: true, state: { courseId, phase } });
127	    }
128	    for (const { courseId, reason } of unassignedCourses) {
129	      consider({ order, assigned: false, state: { courseId, phase, reason } });
130	    }
131	  }
132	
133	  const resolved: ResolvedCourseStates = {
134	    assignedCourses: [],
135	    unassignedCourses: [],
136	  };
137	  for (const { assigned, state } of latestByCourseId.values()) {
138	    if (assigned) {
139	      resolved.assignedCourses.push(state);
140	    } else {
141	      resolved.unassignedCourses.push(state);
142	    }
143	  }
144	
145	  return resolved;
146	}
