157	      if (requestSchema.others) {
158	        lang = Language.zh_TW;
159	        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
160	        // @ts-ignore
161	        const rawLang = z.nativeEnum(Language).safeParse(request.query["lang"]);
162	        if (rawLang.success) {
163	          lang = rawLang.data;
164	        }
165	      }
166	
167	      console.log("Handler received params:", params);
168	      console.log("Request query:", request.query);
169	
170	      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
171	      // @ts-ignore
172	      const res = await handler({
173	        ...params,
174	        ...(lang && { lang }),
175	        ...(userId && { userId }),
176	      });
177	      if (responseSchema) {
178	        reply.status(responseStatusCode).send(res);
179	      } else {
