186	/**
187	 * 建立「已綁定權限檢查函式」的 createRoute，讓後台模組的每個路由只需傳入
188	 * `permission: "vacation-course:manage"` 字串，不用每次重複帶 assertPermission。
189	 *
190	 * @example
191	 *   const createAdminRoute = bindAdminRoute(createAssertPermission(rbacRepo));
192	 *   createAdminRoute({ ..., permission: "vacation-course:manage", handler });
193	 */
194	export function bindAdminRoute(assertPermission: AssertPermission) {
195	  return function createAdminRoute<TParams, TQuery, TBody, TResponse>(
196	    props: Omit<
197	      CreateRouteProps<TParams, TQuery, TBody, TResponse>,
198	      "permission"
199	    > & { permission?: string },
200	  ) {
201	    const { permission: code, ...rest } = props;
202	    return createRoute({
203	      ...rest,
204	      permission: code ? { assert: assertPermission, code } : undefined,
205	    });
206	  };
207	}
