getResultTable: async (
  req: GetResultTableRequest,
): Promise<ResultTable> => {
  const { assignedCourses, unassignedCourses } = await courseTableRepo
    .getCourseTable({
      userId: req.userId,
      semester: req.semester,
      phase: req.phase,
      withAssigned: true,
      withUnassigned: true,
    })
    .catch(handleError);

  // 同上：serial 需要從 courseId 反查，故一律查課程資料
  const rawCourses = await courseRepo.getMany([
    ...assignedCourses.map(({ courseId }) => courseId),
    ...unassignedCourses.map(({ courseId }) => courseId),
  ]);
  const courses = rawCourses.map((course) =>
    formatCourse(course, req.lang),
  );
